using System;

class Program
{
    static string InsertCharacter(string input, int index, char character)
    {
        if (input == null)
            return null;

        if (index < 0)
            index = 0;

        if (index > input.Length)
            index = input.Length;

        string result = input.Substring(0, index) + character + input.Substring(index);
        return result;
    }

    static void Main()
