Here's a C# program that removes all occurrences of a specified item from an array:

```csharp
using System;

class Program
{
    static void Main()
    {
        int[] array = { 1, 2, 3, 4, 5, 2, 3, 4 };
        int itemToRemove = 2;

        // Remove all occurrences of the item
        int[] newArray = RemoveAllOccurrences(array, itemToRemove);

        // Print the result
        Console.WriteLine("Original array:");
        foreach (int num in array)
        {
            Console.Write(num + " ");
        }

        Console.WriteLine("\n\nArray after removing " + itemToRemove + ":");
        foreach (int num in newArray)
        {
            Console.Write(num + " ");
        }
    }

    static int[] RemoveAllOccurrences(int[] array, int item)
    {
        if (array == null || array.Length == 0)
        {
            return new int[0];
        }

        int count = 0;

        // Count the number of occurrences
        foreach (int num in array)
        {
            if (num == item)
            {
                count++;
            }
        }

        // Create a new array with the items that are not equal to the item
        int[] result = new int[count];
        int index = 0;

        foreach (int num in array)
        {
            if (num != item)
            {
                result[index++] = num;
            }
        }

        return result;
    }
}
```

